package com.example.eurostatcrud.repository;

import java.util.List;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

import org.springframework.stereotype.Repository;

import com.example.eurostatcrud.domain.SeriesNote;

@Repository
public class InMemorySeriesNoteRepository implements SeriesNoteRepository {

    private final ConcurrentHashMap<Long, SeriesNote> notes = new ConcurrentHashMap<>();
    private final AtomicLong sequence = new AtomicLong();

    @Override
    public List<SeriesNote> findAll() {
        return List.copyOf(notes.values());
    }

    @Override
    public Optional<SeriesNote> findById(long id) {
        return Optional.ofNullable(notes.get(id));
    }

    @Override
    public Optional<SeriesNote> findByPeriod(String period) {
        return notes.values().stream()
                .filter(note -> note.period().equals(period))
                .findFirst();
    }

    @Override
    public boolean existsByPeriod(String period) {
        return findByPeriod(period).isPresent();
    }

    @Override
    public synchronized SeriesNote save(SeriesNote note) {
        long id = note.id() == null ? sequence.incrementAndGet() : note.id();
        SeriesNote saved = new SeriesNote(
                id,
                note.period(),
                note.noteText(),
                note.tag(),
                note.rating(),
                note.pinned(),
                note.createdAt(),
                note.updatedAt());
        notes.put(id, saved);
        return saved;
    }

    @Override
    public synchronized void deleteById(long id) {
        notes.remove(id);
    }

    @Override
    public long count() {
        return notes.size();
    }

    @Override
    public synchronized void clear() {
        notes.clear();
        sequence.set(0);
    }
}

package com.example.eurostatcrud.service;

import java.util.Comparator;
import java.util.List;
import java.util.Optional;

import org.springframework.stereotype.Service;

import com.example.eurostatcrud.domain.EurostatSeries;
import com.example.eurostatcrud.domain.PageResult;
import com.example.eurostatcrud.domain.SeriesSummary;
import com.example.eurostatcrud.repository.EurostatRepository;

@Service
public class EurostatService {

    private final EurostatRepository repository;

    public EurostatService(EurostatRepository repository) {
        this.repository = repository;
    }

    public List<EurostatSeries> listAll() {
        return repository.findAll().stream()
                .sorted(Comparator.comparing(EurostatSeries::period).reversed())
                .toList();
    }

    public Optional<EurostatSeries> findByPeriod(String period) {
        return repository.findByPeriod(period);
    }

    public boolean existsByPeriod(String period) {
        return repository.existsByPeriod(period);
    }

    public SeriesSummary summary() {
        List<EurostatSeries> all = listAll();
        if (all.isEmpty()) {
            return new SeriesSummary(0, null, null, null, null, 0.0);
        }
        EurostatSeries latest = all.get(0);
        EurostatSeries earliest = all.get(all.size() - 1);
        double average = all.stream()
                .mapToDouble(EurostatSeries::unemploymentRatePct)
                .average()
                .orElse(0.0);
        return new SeriesSummary(
                all.size(),
                latest.period(),
                latest.unemploymentRatePct(),
                earliest.period(),
                earliest.unemploymentRatePct(),
                average);
    }

    public PageResult<EurostatSeries> page(int page, int size, String year) {
        List<EurostatSeries> all = listAll();
        List<EurostatSeries> filtered = (year == null || year.isBlank())
                ? all
                : all.stream().filter(series -> series.period().startsWith(year + "-")).toList();

        int safeSize = Math.max(1, Math.min(size, 100));
        int totalPages = filtered.isEmpty() ? 0 : (int) Math.ceil((double) filtered.size() / safeSize);
        int safePage = totalPages == 0 ? 0 : Math.max(0, Math.min(page, totalPages - 1));
        int from = safePage * safeSize;
        int to = Math.min(from + safeSize, filtered.size());
        List<EurostatSeries> items = from >= filtered.size()
                ? List.of()
                : List.copyOf(filtered.subList(from, to));

        return new PageResult<>(
                items,
                safePage,
                safeSize,
                filtered.size(),
                totalPages,
                safePage > 0,
                safePage + 1 < totalPages);
    }

    public List<String> years() {
        return listAll().stream()
                .map(series -> series.period().substring(0, 4))
                .distinct()
                .sorted(Comparator.reverseOrder())
                .toList();
    }

    public int ping() {
        return repository.ping();
    }
}

package com.example.eurostatcrud.service;

import java.time.Instant;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;

import org.springframework.stereotype.Service;

import com.example.eurostatcrud.domain.SeriesNote;
import com.example.eurostatcrud.exception.DuplicateNoteException;
import com.example.eurostatcrud.exception.NoteNotFoundException;
import com.example.eurostatcrud.exception.UnknownPeriodException;
import com.example.eurostatcrud.repository.SeriesNoteRepository;
import com.example.eurostatcrud.web.form.SeriesNoteForm;

@Service
public class SeriesNoteService {

    private final SeriesNoteRepository repository;
    private final EurostatService eurostatService;

    public SeriesNoteService(SeriesNoteRepository repository, EurostatService eurostatService) {
        this.repository = repository;
        this.eurostatService = eurostatService;
    }

    public List<SeriesNote> listAll() {
        return repository.findAll().stream()
                .sorted(Comparator.comparing(SeriesNote::pinned).reversed()
                        .thenComparing(SeriesNote::updatedAt, Comparator.reverseOrder()))
                .toList();
    }

    public SeriesNote get(long id) {
        return repository.findById(id)
                .orElseThrow(() -> new NoteNotFoundException("Note " + id + " was not found."));
    }

    public SeriesNote create(SeriesNoteForm form) {
        String period = normalizePeriod(form.getPeriod());
        validatePeriodExists(period);
        if (repository.existsByPeriod(period)) {
            throw new DuplicateNoteException("A note already exists for period " + period + ".");
        }
        Instant now = Instant.now();
        SeriesNote note = new SeriesNote(
                null,
                period,
                form.getNoteText().trim(),
                normalizeTag(form.getTag()),
                form.getRating(),
                form.isPinned(),
                now,
                now);
        return repository.save(note);
    }

    public SeriesNote update(long id, SeriesNoteForm form) {
        SeriesNote existing = get(id);
        String period = normalizePeriod(form.getPeriod());
        if (!period.equals(existing.period())) {
            validatePeriodExists(period);
            if (repository.existsByPeriod(period)) {
                throw new DuplicateNoteException("A note already exists for period " + period + ".");
            }
        }
        SeriesNote updated = new SeriesNote(
                existing.id(),
                period,
                form.getNoteText().trim(),
                normalizeTag(form.getTag()),
                form.getRating(),
                form.isPinned(),
                existing.createdAt(),
                Instant.now());
        return repository.save(updated);
    }

    public void delete(long id) {
        if (repository.findById(id).isEmpty()) {
            throw new NoteNotFoundException("Note " + id + " was not found.");
        }
        repository.deleteById(id);
    }

    public Optional<SeriesNote> findByPeriod(String period) {
        return repository.findByPeriod(period);
    }

    public long count() {
        return repository.count();
    }

    private String normalizePeriod(String raw) {
        if (raw == null || raw.isBlank()) {
            throw new UnknownPeriodException("Period is required.");
        }
        String period = raw.trim();
        if (!period.matches("^\\d{4}-(0[1-9]|1[0-2])$")) {
            throw new UnknownPeriodException("Period must be a valid month such as 2025-07.");
        }
        return period;
    }

    private void validatePeriodExists(String period) {
        if (!eurostatService.existsByPeriod(period)) {
            throw new UnknownPeriodException("No Eurostat observation exists for period " + period + ".");
        }
    }

    private String normalizeTag(String tag) {
        return (tag == null || tag.isBlank()) ? null : tag.trim();
    }
}

package com.example.eurostatcrud.service;

import java.time.Instant;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.stereotype.Component;

import com.example.eurostatcrud.domain.SeriesNote;
import com.example.eurostatcrud.repository.SeriesNoteRepository;

@Component
public class DemoNoteSeeder implements ApplicationRunner {

    private final SeriesNoteRepository repository;
    private final boolean seedNotes;

    public DemoNoteSeeder(
            SeriesNoteRepository repository,
            @Value("${app.demo.seed-notes:true}") boolean seedNotes) {
        this.repository = repository;
        this.seedNotes = seedNotes;
    }

    @Override
    public void run(ApplicationArguments args) {
        if (!seedNotes || repository.count() > 0) {
            return;
        }
        Instant now = Instant.now();
        repository.save(new SeriesNote(
                null, "1997-01", "First observation in the series.", "history", 4, false,
                now.minusSeconds(3), now.minusSeconds(3)));
        repository.save(new SeriesNote(
                null, "2024-01", "Mid-series comparison point.", "comparison", 3, false,
                now.minusSeconds(2), now.minusSeconds(2)));
        repository.save(new SeriesNote(
                null, "2025-07", "Latest observation in the demo dataset.", "latest", 5, true,
                now.minusSeconds(1), now.minusSeconds(1)));
    }
}

package com.example.eurostatcrud.web.form;

import com.example.eurostatcrud.domain.SeriesNote;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

public class SeriesNoteForm {

    private Long id;

    @NotBlank(message = "Period is required.")
    @Pattern(regexp = "^\\d{4}-(0[1-9]|1[0-2])$", message = "Period must be a valid month such as 2025-07.")
    private String period;

    @NotBlank(message = "Note text is required.")
    @Size(max = 2000, message = "Note text must be at most 2000 characters.")
    private String noteText;

    @Size(max = 32, message = "Tag must be at most 32 characters.")
    private String tag;

    @Min(value = 1, message = "Rating must be between 1 and 5.")
    @Max(value = 5, message = "Rating must be between 1 and 5.")
    private Integer rating;

    private boolean pinned;

    public static SeriesNoteForm from(SeriesNote note) {
        SeriesNoteForm form = new SeriesNoteForm();
        form.setId(note.id());
        form.setPeriod(note.period());
        form.setNoteText(note.noteText());
        form.setTag(note.tag());
        form.setRating(note.rating());
        form.setPinned(note.pinned());
        return form;
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getPeriod() {
        return period;
    }

    public void setPeriod(String period) {
        this.period = period;
    }

    public String getNoteText() {
        return noteText;
    }

    public void setNoteText(String noteText) {
        this.noteText = noteText;
    }

    public String getTag() {
        return tag;
    }

    public void setTag(String tag) {
        this.tag = tag;
    }

    public Integer getRating() {
        return rating;
    }

    public void setRating(Integer rating) {
        this.rating = rating;
    }

    public boolean isPinned() {
        return pinned;
    }

    public void setPinned(boolean pinned) {
        this.pinned = pinned;
    }
}

